import {openPaymentPlan,latestPaymentPlan} from './payment-plan.mjs';
import {textoAvance} from './payment-plan-rooms.mjs';
import {calculatePayment} from './payment-calculation.mjs';
import {loadVendor} from './web-store.mjs';
import {leerItemizado} from './avance-model.mjs';
let priceItems=new Map();
const root=document.querySelector('#root'),message=document.querySelector('#message');let token='',user,rows=[],contractors=[];const esc=v=>String(v??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');
async function api(route='',body){const r=await fetch('/api/payments'+route,{method:body?'POST':'GET',cache:'no-store',headers:{'Content-Type':'application/json','X-Payment-Session':token},...(body?{body:JSON.stringify(body)}:{})});const data=await r.json();if(!r.ok){if(r.status===401&&token){token='';login();}throw Error(data.error);}return data;}
function login(){root.innerHTML='<h2>Acceso personal</h2><form id="login"><label>Correo electrónico<input type="email" name="username" autocomplete="username" required></label><label>Contraseña<input name="password" type="password" autocomplete="current-password" required></label><button>Entrar</button></form>';root.querySelector('form').onsubmit=async e=>{e.preventDefault();try{const data=await api('/login',Object.fromEntries(new FormData(e.target)));token=data.token;user=data.user;e.target.reset();await load();}catch(e){message.textContent=e.message;}};}
async function load(){const data=await api();let prices;try{prices=await api('/prices');}catch(error){message.textContent=error.message;prices={items:[]};}priceItems=new Map(prices.items.map(i=>[i.code,i]));rows=data.payments;contractors=data.contractors;message.textContent='';root.innerHTML='<p>Usuario: '+esc(user.username)+' · '+esc(user.role)+'</p><button id="logout">Cerrar sesión</button><button id="new">Nuevo estado de pago</button><section id="editor"></section><section><h2>Matriz de precios</h2><p>'+priceItems.size+' partidas del catálogo compartido.</p><label>Cargar Excel Rev01 al catálogo compartido (solo aprobador)<input type="file" id="sharedPrices" accept=".xlsx,.xls"></label><p>Catálogo compartido Rev01. El monto de pago se ingresa por separado del precio unitario.</p></section><h2>Registro histórico</h2><p>Una fila por estado de pago. Versiones anteriores conserva cada guardado.</p>'+paymentTable(rows);root.querySelector('#logout').onclick=async()=>{try{await api('/logout',{});}finally{token='';rows=[];login();}};root.querySelector('#sharedPrices').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(user.role!=='approver')throw Error('Solo un aprobador puede cargar precios');await loadVendor('xlsx');const parsed=leerItemizado(XLSX.read(await f.arrayBuffer(),{type:'array'}),XLSX),items=[...parsed.items.values()].map(i=>({code:i.code,desc:i.desc,unit:i.unit,pu:i.pu,source:f.name,sourceRow:i.fila}));for(let n=0;n<items.length;n+=100){message.textContent='Cargando '+n+' de '+items.length+' partidas…';await api('/prices',{items:items.slice(n,n+100)});}await load();message.textContent='Catálogo compartido cargado: '+items.length+' partidas.';}catch(error){message.textContent=error.message+' Puedes repetir la carga; los códigos existentes se actualizan.';}};root.querySelector('#new').onclick=()=>edit();bindPaymentRows(root,rows);}
function edit(record={}){
 const area=root.querySelector('#editor');area.innerHTML='<h2>'+ (record.id?'Editar':'Nuevo')+'</h2><form><label>Subcontratista<select name="contractor" required><option value="">Selecciona un subcontratista</option>'+contractors.map(c=>'<option value="'+esc(c.label)+'" '+(record.contractor===c.label?'selected':'')+'>'+esc(c.label)+'</option>').join('')+'</select></label><label>Período<input type="month" name="period" value="'+esc(record.period)+'" required></label><section><h3>Plano de avance</h3><button type="button" id="drawPaymentPlan">Abrir plano y dibujar avance</button><p id="paymentPlanInfo"></p></section><h3>Partidas</h3><div id="items"></div><button type="button" id="add">Añadir partida</button><label>Retención (%)<select id="retentionChoice" required>'+[0,5,7.5,10,12.5,15].map(n=>'<option value="'+n+'">'+String(n).replace('.',',')+' %</option>').join('')+'<option value="other">Otro porcentaje</option></select></label><label id="customPercentLabel" hidden>Otro porcentaje<input id="customPercent" type="number" min="0" max="100" step="any"></label><p id="legacyPaymentNote"></p><section id="paymentTotals" aria-live="polite"></section><label>Estado<select name="status">'+['Borrador','En revisión','Aprobado','Rechazado'].map(s=>'<option '+(record.status===s?'selected':'')+'>'+s+'</option>').join('')+'</select></label><button>Guardar</button></form>';
 let paymentPlan=structuredClone(record.plan||{schema:1,floors:{}});const contractor=area.querySelector('[name=contractor]'),planInfo=area.querySelector('#paymentPlanInfo');
 // Trazos, recintos marcados y avance por superficie de cada piso dibujado (calculado en el plano).
 const showPlan=()=>{const floorsDone=Object.entries(paymentPlan.floors).filter(([,f])=>f.strokes.length||Object.keys(f.rooms||{}).length),strokes=floorsDone.reduce((n,[,f])=>n+f.strokes.length,0),marked=floorsDone.reduce((n,[,f])=>n+Object.keys(f.rooms||{}).length,0);planInfo.textContent=(floorsDone.length?strokes+' trazos y '+marked+' recintos marcados. '+floorsDone.map(([k,f])=>({'N-1':'Piso −1',N01:'Piso 1',N02:'Piso 2',N03:'Piso 3'}[k])+': '+textoAvance(f.avance)).join(' · ')+'. ':'Sin dibujo. ')+'Guarda el estado de pago para conservarlo en la nube.';};showPlan();
 contractor.onchange=()=>{if(Object.values(paymentPlan.floors).some(f=>f.strokes.length||Object.keys(f.rooms||{}).length)&&!confirm('Cambiar subcontratista reemplazará el dibujo de este formulario por su avance anterior. ¿Continuar?')){contractor.value=contractor.dataset.previous||record.contractor||'';return;}paymentPlan=latestPaymentPlan(rows,contractor.value);contractor.dataset.previous=contractor.value;showPlan();};
 area.querySelector('#drawPaymentPlan').onclick=()=>{if(!contractor.value){message.textContent='Selecciona primero el subcontratista';return;}openPaymentPlan(paymentPlan,plan=>{paymentPlan=plan;showPlan();});};
 const items=area.querySelector('#items'),choice=area.querySelector('#retentionChoice'),custom=area.querySelector('#customPercent');const money=n=>'$'+n.toLocaleString('es-CL');
 if(record.id&&record.retentionPercent==null){area.querySelector('#legacyPaymentNote').textContent='Registro anterior: retención guardada '+money(record.retention)+'. Confirma el porcentaje y las cantidades antes de guardar.';choice.value='other';}
 else if(record.retentionPercent!=null){choice.value=[0,5,7.5,10,12.5,15].includes(record.retentionPercent)?String(record.retentionPercent):'other';custom.value=record.retentionPercent;}
 function values(){return calculatePayment([...items.children].map(div=>({...div.paymentItem,description:div.querySelector('.selectedDescription').value,quantity:div.querySelector('.quantity').value===''?NaN:Number(div.querySelector('.quantity').value)})),choice.value==='other'?(custom.value===''?NaN:Number(custom.value)):Number(choice.value));}
 function recalc(){area.querySelector('#customPercentLabel').hidden=choice.value!=='other';custom.required=choice.value==='other';try{const result=values();[...items.children].forEach((div,i)=>div.querySelector('.lineAmount').textContent=money(result.items[i].amount));area.querySelector('#paymentTotals').textContent='Subtotal: '+money(result.amount)+' · Retención ('+result.retentionPercent+' %): '+money(result.retention)+' · Neto a pagar: '+money(result.net);}catch(error){area.querySelector('#paymentTotals').textContent=error.message;}}
 const add=(item={})=>{const div=document.createElement('div');div.className='paymentLine';div.paymentItem={code:item.code,unit:item.unit,unitPrice:item.unitPrice};div.innerHTML='<label>Partida<input class="selectedDescription" readonly placeholder="Selecciona una partida" value="'+esc(item.description)+'"></label><button type="button" class="choosePrice">Seleccionar partida ▾</button><div class="priceFacts"><label>Unidad<input class="lineUnit" readonly value="'+esc(item.unit)+'"></label><label>Precio unitario CLP<input class="linePrice" readonly value="'+esc(item.unitPrice)+'"></label></div><label>Cantidad<input class="quantity" type="number" min="0" step="any" required value="'+(item.quantity??'')+'"></label><p>Importe: <strong class="lineAmount">'+money(item.amount||0)+'</strong></p><button type="button" class="removeLine">Quitar</button>';
 div.querySelector('.choosePrice').onclick=()=>openPricePicker(selected=>{div.paymentItem={code:selected.code,unit:selected.unit,unitPrice:Number(selected.pu)};div.querySelector('.selectedDescription').value=selected.code+' · '+selected.desc;div.querySelector('.lineUnit').value=selected.unit;div.querySelector('.linePrice').value=selected.pu;recalc();});div.querySelector('.selectedDescription').onclick=()=>div.querySelector('.choosePrice').click();div.querySelector('.quantity').oninput=recalc;div.querySelector('.removeLine').onclick=()=>{div.remove();recalc();};items.append(div);};
 (record.items||[{}]).forEach(add);area.querySelector('#add').onclick=()=>{add();recalc();};choice.onchange=recalc;custom.oninput=recalc;recalc();area.querySelector('form').onsubmit=async e=>{e.preventDefault();try{const calc=values();if(!calc.items.length)throw Error('Añade al menos una partida');await api('',{...Object.fromEntries(new FormData(e.target)),...calc,plan:paymentPlan,id:record.id,version:record.version});await load();message.textContent='Estado de pago guardado.';}catch(error){message.textContent=error.message;}};area.scrollIntoView({block:'start'});
}
function openPricePicker(onSelect){
 const dialog=document.createElement('dialog');dialog.className='pricePicker';dialog.innerHTML='<header><h2>Seleccionar partida</h2><button type="button" class="closePicker" aria-label="Cerrar catálogo">Cerrar ✕</button></header><label>Buscar código o descripción<input class="priceQuery" type="search" placeholder="Ej.: baranda, pintura, 5.1…"></label><p class="priceCount" role="status"></p><div class="priceAlternatives"></div><footer><button type="button" class="prevPrice">Anterior</button><span class="pricePage"></span><button type="button" class="nextPrice">Siguiente</button></footer>';
 document.body.append(dialog);let page=0;const norm=v=>String(v).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase(),query=dialog.querySelector('.priceQuery'),list=dialog.querySelector('.priceAlternatives');const close=()=>{dialog.close();dialog.remove();};dialog.querySelector('.closePicker').onclick=close;dialog.oncancel=e=>{e.preventDefault();close();};
 function draw(){const words=norm(query.value).split(/\s+/).filter(Boolean),matches=[...priceItems.values()].filter(i=>words.every(w=>norm(i.code+' '+i.desc+' '+i.unit).includes(w))).sort((a,b)=>a.code.localeCompare(b.code,'es',{numeric:true})),pages=Math.max(1,Math.ceil(matches.length/50));page=Math.min(page,pages-1);dialog.querySelector('.priceCount').textContent=matches.length+' alternativas de '+priceItems.size+' partidas';list.replaceChildren();for(const item of matches.slice(page*50,page*50+50)){const button=document.createElement('button');button.type='button';button.className='priceAlternative';button.innerHTML='<strong>'+esc(item.code)+' · '+esc(item.desc)+'</strong><small>Unidad: '+esc(item.unit)+' · Precio unitario: $'+esc(Number(item.pu).toLocaleString('es-CL'))+'</small>';button.onclick=()=>{onSelect(item);close();};list.append(button);}if(!matches.length)list.textContent=priceItems.size?'No hay coincidencias. Prueba otra descripción o código.':'No hay partidas cargadas en el catálogo compartido.';dialog.querySelector('.pricePage').textContent=(page+1)+' / '+pages;dialog.querySelector('.prevPrice').disabled=page===0;dialog.querySelector('.nextPrice').disabled=page+1>=pages;list.scrollTop=0;}
 query.oninput=()=>{page=0;draw();};dialog.querySelector('.prevPrice').onclick=()=>{page--;draw();};dialog.querySelector('.nextPrice').onclick=()=>{page++;draw();};draw();dialog.showModal();dialog.querySelector('.closePicker').focus();
}
login();

function paymentTable(records){const money=n=>'$'+Number(n||0).toLocaleString('es-CL');return '<div class="paymentHistoryScroll"><table class="paymentHistory"><thead><tr><th>Período</th><th>Subcontratista</th><th>Subtotal</th><th>Retención</th><th>Neto</th><th>Estado</th><th>Responsable / fecha</th><th>Versión</th><th>Acciones</th></tr></thead><tbody>'+records.map((r,i)=>'<tr><td>'+esc(r.period)+'</td><td>'+esc(r.contractor)+'</td><td>'+money(r.amount)+'</td><td>'+esc(r.retentionPercent!=null?r.retentionPercent+' % · ':'')+money(r.retention)+'</td><td>'+money(r.net)+'</td><td>'+esc(r.status)+'</td><td>'+esc(r.by)+'<br>'+esc(r.at)+'</td><td>'+esc(r.version)+'</td><td><button type="button" data-plan="'+i+'" '+(r.plan?'':'disabled')+'>Ver plano</button><button type="button" data-edit="'+i+'">Ver / editar</button><button type="button" data-history="'+i+'">Versiones anteriores</button></td></tr>').join('')+'</tbody></table></div>'+(records.length?'':'<p>Todavía no hay pagos guardados.</p>');}
function bindPaymentRows(container,records){container.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>edit(records[Number(b.dataset.edit)]));container.querySelectorAll('[data-plan]').forEach(b=>b.onclick=()=>openPaymentPlan(records[Number(b.dataset.plan)].plan,()=>{},{readOnly:true}));container.querySelectorAll('[data-history]').forEach(b=>b.onclick=async()=>{try{const payment=records[Number(b.dataset.history)],data=await api('/history?id='+encodeURIComponent(payment.id)),dialog=document.createElement('dialog');dialog.className='paymentVersionDialog';dialog.innerHTML='<h2>Versiones guardadas</h2><p>'+esc(payment.contractor)+' · '+esc(payment.period)+'</p>'+paymentTable(data.history)+'<button type="button" class="closeVersions">Cerrar</button>';document.body.append(dialog);dialog.showModal();dialog.querySelectorAll('[data-edit],[data-history]').forEach(node=>node.remove());dialog.querySelectorAll('[data-plan]').forEach(button=>button.onclick=()=>openPaymentPlan(data.history[Number(button.dataset.plan)].plan,()=>{},{readOnly:true}));dialog.querySelector('.closeVersions').onclick=()=>dialog.remove();dialog.oncancel=()=>dialog.remove();}catch(error){message.textContent=error.message;}});}
